/* Buildless HTML frontend. All state is loaded from the Express API. */
const $ = selector => document.querySelector(selector);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' })[c]);
const paths = {
  grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',
  cpu:'M7 7h10v10H7z M9 1v4m6-4v4M9 19v4m6-4v4M1 9h4m-4 6h4m14-6h4m-4 6h4 M10 10h4v4h-4z',
  users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 3a4 4 0 0 1 0 8m6 10v-2a4 4 0 0 0-3-3.9 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',
  chart:'M3 3v18h18 M7 14l4-5 4 3 5-7',
  command:'m8 8-4 4 4 4m8-8 4 4-4 4m-3-11-2 14',
  bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',
  audit:'M9 3H5v18h14V3h-4 M9 2h6v4H9z M8 11h8m-8 4h6',
  settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3l1-2h4l1 2 3 2 2 .5 2 3-1 2v3l1 2-2 3-2 .5-3 2-1 2h-4l-1-2-3-2-2-.5-2-3 1-2v-3l-1-2 2-3 2-.5z',
  search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',
  plus:'M12 5v14M5 12h14',arrow:'M5 12h14m-5-5 5 5-5 5', chevrons:'m9 9 3-3 3 3m-6 6 3 3 3-3',
  building:'M4 21V3h12v18M2 21h20M16 9h4v12M8 7h4m-4 4h4m-4 4h4m-4 6v-2h4v2',
  book:'M12 5c-4-3-7-2-10-1v16c4-2 7-2 10 0 3-2 6-2 10 0V4c-3-1-6-2-10 1Zm0 0v15',
  logout:'M9 3H3v18h6 M9 12h12m-4-4 4 4-4 4',calendar:'M4 5h16v16H4zM8 3v4m8-4v4M4 11h16',
  thermo:'M9 14V5a3 3 0 0 1 6 0v9a5 5 0 1 1-6 0 M12 8v10',
  bulb:'M9 18h6m-5 3h4M8 14a7 7 0 1 1 8 0l-1 2H9z',
  drop:'M12 2C9 7 5 11 5 15a7 7 0 0 0 14 0c0-4-4-8-7-13Z',
  wifi:'M2 8a16 16 0 0 1 20 0M5 12a11 11 0 0 1 14 0m-11 4a6 6 0 0 1 8 0M12 20h.01',
  activity:'M2 12h5l3-9 4 18 3-9h5',shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6z m-5 10 3 3 6-6',
  alert:'m12 3 10 18H2z M12 9v5m0 3h.01',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',
  download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',refresh:'M20 7v5h-5M4 17v-5h5 M6 5a8 8 0 0 1 14 7M4 12a8 8 0 0 0 14 7',
  more:'M5 12h.01M12 12h.01M19 12h.01',menu:'M3 6h18M3 12h18M3 18h18',edit:'m16 3 5 5-12 12-6 1 1-6Z M13 6l5 5',
  clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',lock:'M5 10h14v11H5zM8 10V6a4 4 0 0 1 8 0v4',
  fan:'M12 12c-5-7-5-10-1-10 5 0 7 5 1 10Zm0 0c8-1 11 0 9 4-2 5-8 4-9-4Zm0 0c-3 8-5 10-8 7-3-4 1-9 8-7Z',
};
const icon = (name, cls='') => `<svg class="icon ${cls}" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[name] || paths.cpu}"/></svg>`;
function icons() { document.querySelectorAll('[data-icon]').forEach(e => { e.innerHTML=icon(e.dataset.icon); e.removeAttribute('data-icon'); }); }
const S = { user:null, csrf:'', demo:true, page:'overview', search:'', filter:'all', hours:24, chartHours:24, devices:[], users:[], overview:null, chart:null, socket:null, renderVersion:0 };
const pages = [ ['overview','grid','Tổng quan'],['homes','building','Ngôi nhà'],['devices','cpu','Thiết bị'],['users','users','Người dùng'],['telemetry','chart','Dữ liệu cảm biến'],['commands','command','Lịch sử điều khiển'],['alerts','bell','Cảnh báo'],['audit','audit','Nhật ký hệ thống'],['settings','settings','Cài đặt'] ];
const lifeNames={registered:'Đã đăng ký',provisioned:'Đã cấp quyền',active:'Đã kích hoạt',maintenance:'Bảo trì',locked:'Đã khóa',decommissioned:'Ngừng sử dụng'};
const commandNames={pending:'Chờ xác nhận',applied:'Đã áp dụng',failed:'Thất bại',timeout:'Hết thời gian',cancelled:'Đã hủy'};
const actionNames={'room.created':'Tạo phòng','room.updated':'Đổi tên phòng','room.deleted':'Xóa phòng','home.created':'Tạo nhà','home.updated':'Cập nhật nhà','member.invited':'Mời viewer','member.joined':'Tham gia nhà','member.removed':'Thu hồi thành viên','member.invite_revoked':'Hủy lời mời','device.claimed':'Nhận thiết bị','device.moved':'Đổi tên / chuyển phòng','auth.login':'Đăng nhập hệ thống','auth.logout':'Đăng xuất hệ thống','auth.failed':'Đăng nhập thất bại','system.seed':'Khởi tạo không gian demo','device.created':'Đăng ký thiết bị mới','device.updated':'Cập nhật thông tin thiết bị','device.lifecycle':'Thay đổi vòng đời thiết bị','device.config':'Gửi cấu hình thiết bị','device.actuator':'Gửi lệnh điều khiển','user.created':'Tạo tài khoản','user.updated':'Cập nhật tài khoản','alert.acknowledged':'Xác nhận cảnh báo','settings.updated':'Cập nhật cài đặt','telemetry.export':'Xuất dữ liệu cảm biến','demo.connection':'Thử kết nối node','mqtt.rejected':'Từ chối bản tin MQTT','user.password_changed':'Đổi mật khẩu'};
const dt = (value,full=false) => value ? new Intl.DateTimeFormat('vi-VN',{timeZone:'Asia/Ho_Chi_Minh', ...(full?{day:'2-digit',month:'2-digit',year:'numeric'}:{}),hour:'2-digit',minute:'2-digit',...(full?{}:{second:'2-digit'})}).format(new Date(value)) : 'Chưa kết nối';
const relative = value => { const seconds=Math.floor((Date.now()-new Date(value))/1000); return seconds<60?'Vừa xong':seconds<3600?`${Math.floor(seconds/60)} phút trước`:seconds<86400?`${Math.floor(seconds/3600)} giờ trước`:dt(value,true); };
const initials = name => name.split(' ').filter(Boolean).slice(-2).map(v=>v[0]).join('').toUpperCase();
const badge = (text,color='') => `<span class="badge ${color}">${esc(text)}</span>`;
const onlineBadge = d => `<span class="badge ${d.connection==='online'?'green':d.connection==='unknown'?'orange':''}">${d.connection==='online'?'<span class="status-dot"></span>':''}${d.connection==='online'?'Online':d.connection==='unknown'?'Chưa rõ kết nối':'Offline'}</span>`;
const lifecycleBadge = d => badge(lifeNames[d.lifecycle],({active:'green',provisioned:'blue',maintenance:'orange',locked:'red',decommissioned:''})[d.lifecycle]);
const commandBadge = cmd => badge(commandNames[cmd.status],({applied:'green',pending:'orange',failed:'red',timeout:'red'})[cmd.status]);
const canWrite = d => S.user.role==='admin'||(S.user.role==='operator'&&d.owner_id===S.user.id);
const matches = (...values) => !S.search || values.join(' ').toLocaleLowerCase('vi').includes(S.search.toLocaleLowerCase('vi'));
const button = (action,text,ico='plus',cls='btn-primary',data='') => `<button class="btn ${cls}" data-action="${action}" ${data}>${icon(ico)}${text}</button>`;
const empty = (title,description='Dữ liệu sẽ xuất hiện ở đây khi hệ thống có hoạt động.',ico='cpu') => `<div class="empty-state">${icon(ico)}<strong>${title}</strong>${description}</div>`;
function heading(title,desc,actions='',eyebrow='SMART ROOM / ADMIN WORKSPACE'){return `<div class="page-heading"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${desc}</p></div><div class="heading-actions">${actions}</div></div>`;}
function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.innerHTML=icon(error?'alert':'check')+`<span>${esc(message)}</span>`;if($('#toasts').children.length>=3)$('#toasts').firstElementChild.remove();$('#toasts').append(el);setTimeout(()=>el.remove(),5000);}
async function api(path,options={}){
  const response=await fetch('/api'+path,{...options,headers:{'Content-Type':'application/json','X-CSRF-Token':S.csrf,...options.headers},...(options.body?{body:JSON.stringify(options.body)}:{})});
  if(response.status===401){if(!S.loggingOut)location.replace('/login');throw new Error('Phiên đăng nhập đã kết thúc.');}
  const data=await response.json();if(!response.ok)throw new Error(data.error||'Không thể hoàn tất thao tác.');return data;
}
function navigation(){
  $('#navigation').innerHTML=pages.filter(([id])=>S.user.role==='admin'||!['users','audit'].includes(id)).map(([id,ico,label])=>`<a href="#${id}" class="nav-item ${S.page===id?'active':''}" ${S.page===id?'aria-current="page"':''}>${icon(ico)}${label}${id==='alerts'&&S.overview?.counts.alerts?`<span class="nav-count">${S.overview.counts.alerts}</span>`:''}</a>`).join('');
  $('#breadcrumb-page').textContent=pages.find(p=>p[0]===S.page)?.[2]||'Tài liệu';
  $('#sidebar-name').textContent=S.user.name;$('#sidebar-role').textContent={admin:'Administrator',operator:'Operator',viewer:'Viewer'}[S.user.role];
  $('#avatar').textContent=$('#top-avatar').textContent=initials(S.user.name);
  $('#notification-dot').hidden=!S.overview?.counts.alerts;
}
function demoBanner(){return S.demo?`<div class="demo-banner"><div>${icon('activity')}<span><strong>Không gian demo</strong> &nbsp; Hai node ESP32 đang được giả lập. Dữ liệu và phản hồi lệnh dùng để phát triển backend.</span></div><a href="#guide">Hướng dẫn tích hợp ↗</a></div>`:'';}
function nodeCell(d){return `<div class="table-device"><div class="node-icon ${d.profile}">${icon(d.profile==='climate'?'thermo':'bulb')}</div><div><strong>${esc(d.name)}</strong><span class="subtext mono">${esc(d.id)}</span></div></div>`;}
function deviceTable(devices){devices=devices.filter(d=>matches(d.name,d.id,d.location));return `<div class="table-wrap"><table><thead><tr><th>THIẾT BỊ</th><th>VỊ TRÍ</th><th>KẾT NỐI</th><th>VÒNG ĐỜI</th><th>LẦN CUỐI NHẬN TIN</th><th></th></tr></thead><tbody>${devices.map(d=>`<tr><td>${nodeCell(d)}</td><td>${esc(d.location)}</td><td>${onlineBadge(d)}</td><td>${lifecycleBadge(d)}</td><td>${dt(d.last_seen)}</td><td><button class="icon-btn" data-action="device-detail" data-id="${esc(d.id)}" aria-label="Chi tiết ${esc(d.name)}">${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>${devices.length?'':empty('Chưa có thiết bị phù hợp','Đăng ký node mới hoặc thay đổi bộ lọc.')}<div class="table-footer"><span>Hiển thị ${devices.length} thiết bị</span><span>Mỗi node có định danh & quyền kết nối riêng</span></div>`;}
function alertItem(a,full=false){return `<div class="alert-item"><span class="alert-symbol">${icon(a.kind==='offline'?'wifi':['fault','gas'].includes(a.kind)?'alert':'thermo')}</span><div><strong>${esc(a.device_name||S.devices.find(d=>d.id===a.device_id)?.name||a.device_id)} ${a.status==='acknowledged'?badge('Đã xác nhận','green'):a.status==='resolved'?badge('Đã hết bất thường','green'):''}</strong><p>${esc(a.message)}</p><time>${relative(a.created_at)}</time></div>${full&&a.status==='open'&&S.user.role!=='viewer'?button('ack-alert','Xác nhận','check','btn-secondary btn-small',`data-id="${a.id}"`):''}</div>`;}
function activityRows(rows){return rows.map(a=>`<div class="activity-item"><span class="activity-dot"></span><div><strong>${esc(actionNames[a.action]||a.action)}</strong><p>${esc(a.actor_name)} · ${relative(a.created_at)}</p></div></div>`).join('')||empty('Chưa có hoạt động', '', 'activity');}
function overviewHTML(o){
  const climate=o.devices.find(d=>d.profile==='climate'),lighting=o.devices.find(d=>d.profile==='lighting');
  const cards=[['cpu','Tổng thiết bị',o.counts.devices,'node đã đăng ký','Tất cả thiết bị trong không gian'],['wifi','Đang kết nối',o.counts.online,'node online','Heartbeat được cập nhật liên tục'],['alert','Cảnh báo cần xử lý',o.counts.alerts,'cảnh báo mở','Theo dõi để xử lý kịp thời'],['users',S.user.role==='admin'?'Người dùng':'Quyền truy cập',o.counts.users??o.counts.devices,S.user.role==='admin'?'tài khoản':'thiết bị','Phân quyền theo phạm vi thiết bị']];
  return heading('Tổng quan hệ thống','Chào '+esc(S.user.name)+', đây là không gian IoT của bạn hôm nay.',`<span class="date-filter">${icon('calendar')}${new Intl.DateTimeFormat('vi-VN',{day:'2-digit',month:'short',year:'numeric',timeZone:'Asia/Ho_Chi_Minh'}).format(new Date())}</span>${S.user.role==='admin'?button('new-device','Thêm thiết bị'):button('refresh','Làm mới','refresh','btn-secondary')}`)
  +demoBanner()+(o.devices.length&&!o.counts.online?'<div class="form-note mb-5">Chưa có ESP32 online. Kiểm tra nguồn, Wi-Fi, tài khoản MQTT và heartbeat. Thông số cũ chỉ để tham khảo; chưa thể gửi lệnh.</div>':'')+`<div class="stats-grid">${cards.map(([ico,label,value,unit,note],i)=>`<div class="stat-card"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon(ico)}</span></div><div class="stat-value">${value}<small>${i===0?'/ '+String(value).padStart(2,'0'):''}</small></div><div class="stat-foot"><span class="${i===2?'warning':'positive'}">${i===1?'<span class="status-dot"></span>':i===2?'•':'↗'} ${unit}</span><span>·</span><span>${i===0?'ESP32':i===1?'MQTT':i===2?'Cần chú ý':'RBAC'}</span></div></div>`).join('')}</div>
  <div class="dashboard-columns"><section class="panel"><div class="panel-header"><div><h2 class="panel-title">Diễn biến môi trường</h2><p class="panel-subtitle">Nhiệt độ & độ ẩm · ${esc(climate?.name||'Chưa có node môi trường')}</p></div><div class="segment-control">${[1,6,24].map(h=>`<button data-action="chart-period" data-hours="${h}" class="${S.chartHours===h?'active':''}">${h} giờ</button>`).join('')}</div></div><div class="chart-legend"><span><i class="legend-dot" style="background:#ed9c72"></i>Nhiệt độ (°C)</span><span><i class="legend-dot" style="background:#89a99a"></i>Độ ẩm (%)</span></div><div class="chart-wrap"><canvas id="environment-chart" aria-label="Biểu đồ nhiệt độ và độ ẩm" role="img"></canvas></div></section>
  <section class="panel"><div class="panel-header"><div><h2 class="panel-title">Trạng thái các node</h2><p class="panel-subtitle">Kết nối và đầu ra hiện tại</p></div>${badge('LIVE','green')}</div>${o.devices.slice(0,3).map(d=>`<div class="node-card"><div class="node-card-top"><span class="node-icon ${d.profile}">${icon(d.profile==='climate'?'thermo':'bulb')}</span><div><strong>${esc(d.name)}</strong><small>${esc(d.id)} · ${esc(d.hardware)}</small></div>${onlineBadge(d)}</div><div class="node-card-bottom"><span>${d.profile==='climate'?'Nhiệt độ':'Độ sáng tương đối'} &nbsp; <strong>${d.profile==='climate'?(d.latest?.temperature??'—')+'°C':(d.latest?.light_percent??'—')+'%'}</strong></span><button class="btn btn-secondary btn-small" data-action="device-detail" data-id="${d.id}">${d.profile==='climate'?'Quạt':'Đèn'} ${d.connection!=='online'?'chưa rõ':d.reported_state[d.profile==='climate'?'fan':'light']===undefined?'chưa xác nhận':d.reported_state[d.profile==='climate'?'fan':'light']?'bật':'tắt'} ${icon('arrow')}</button></div></div>`).join('')||empty('Chưa có node')}<div class="node-footer">${icon('refresh')} Cập nhật qua WebSocket · ${o.devices.length} node trong hệ thống</div></section></div>
  <section class="overview-device-section"><div class="section-heading"><h2>Thiết bị của bạn <span>${o.devices.length} thiết bị</span></h2><a href="#devices" class="panel-link">Quản lý tất cả ${icon('arrow')}</a></div><div class="panel">${deviceTable(o.devices)}</div></section>
  <div class="bottom-columns"><section class="panel"><div class="panel-header"><h2 class="panel-title">Cảnh báo gần đây</h2><a href="#alerts" class="panel-link">Xem tất cả ${icon('arrow')}</a></div>${o.alerts.slice(0,2).map(a=>alertItem(a)).join('')||empty('Mọi thứ đang ổn','Chưa có cảnh báo được ghi nhận.','shield')}</section><section class="panel"><div class="panel-header"><h2 class="panel-title">${S.user.role==='admin'?'Hoạt động hệ thống':'Lệnh điều khiển gần đây'}</h2><a href="#${S.user.role==='admin'?'audit':'commands'}" class="panel-link">Xem lịch sử ${icon('arrow')}</a></div>${S.user.role==='admin'?activityRows(o.activity.slice(0,3)):o.commands.slice(0,3).map(c=>`<div class="activity-item">${icon('command')}<div><strong>${esc(c.device_name)} · ${esc(c.kind)}</strong><p>${commandNames[c.status]} · ${relative(c.created_at)}</p></div></div>`).join('')||empty('Chưa có lệnh')}</section></div>`;
}
async function drawChart(selector,rows,light=false){
  if(S.chart){S.chart.destroy();S.chart=null;} const canvas=$(selector);if(!canvas||!window.Chart)return;if(!rows.length){canvas.parentElement.innerHTML='<div class="empty-state"><strong>Chưa có số đo trong khoảng đã chọn</strong><p>ESP32 cần kết nối và gửi dữ liệu cảm biến.</p></div>';return;}
  const series=light?[['light_percent','Độ sáng tương đối (%)','#d3ad62']]:[['temperature','Nhiệt độ (°C)','#ed9c72'],['humidity','Độ ẩm (%)','#87a799']];
  const selected=rows.filter(r=>light?r.light_percent!==null:r.temperature!==null);
  const sampled=selected.filter((_,i)=>i%Math.max(1,Math.floor(selected.length/120))===0);
  const labels=sampled.map(r=>new Intl.DateTimeFormat('vi-VN',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Ho_Chi_Minh'}).format(new Date(r.recorded_at)));
  Chart.defaults.font.family="'Segoe UI', system-ui, sans-serif";Chart.defaults.color='#657387';
  S.chart=new Chart(canvas,{
    type:'line',
    data:{labels,datasets:series.map(([key,label,color],i)=>({label,data:sampled.map(r=>r[key]),borderColor:color,backgroundColor:color+'0d',borderWidth:2,pointRadius:0,pointHitRadius:12,tension:.35,fill:true,yAxisID:i===1?'y1':'y'}))},
    options:{
      responsive:true,maintainAspectRatio:false,animation:false,interaction:{mode:'index',intersect:false},
      plugins:{legend:{display:false},tooltip:{backgroundColor:'#27343c',padding:12,titleFont:{size:10},bodyFont:{size:10}}},
      scales:{
        x:{grid:{display:false},border:{display:false},ticks:{font:{size:12},maxTicksLimit:7,maxRotation:0}},
        y:{min:light?0:20,max:light?100:40,grid:{color:'#f1f3f5',drawTicks:false},border:{display:false},ticks:{font:{size:12},padding:10,stepSize:light?25:5}},
        ...(light?{}:{y1:{position:'right',min:40,max:90,border:{display:false},grid:{display:false},ticks:{font:{size:12},padding:8,stepSize:10}}}),
      },
    },
  });
}
function filtersHTML(selectHTML=''){return `<div class="filters">${selectHTML}<span class="result-count">${S.search?'Kết quả cho “'+esc(S.search)+'”':'Dữ liệu được lưu trên máy chủ'}</span></div>`;}
function devicesHTML(){
  const rows=S.devices.filter(d=>matches(d.name,d.id,d.location)&& (S.filter==='all'||d.lifecycle===S.filter||d.connection===S.filter));
  return heading('Quản lý thiết bị','Theo dõi từng node, cấp quyền kết nối và quản lý toàn bộ vòng đời.',S.user.role==='admin'?button('new-device','Đăng ký thiết bị'):'')+filtersHTML(`<select id="page-filter" aria-label="Lọc thiết bị"><option value="all">Tất cả thiết bị</option>${['online','offline','registered','provisioned','active','maintenance','locked','decommissioned'].map(s=>`<option value="${s}" ${S.filter===s?'selected':''}>${lifeNames[s]||s}</option>`).join('')}</select>`)+`<div class="device-grid">${rows.map(d=>`<article class="device-full-card"><div class="node-card-top"><span class="node-icon ${d.profile}">${icon(d.profile==='climate'?'thermo':'bulb')}</span><div><strong>${esc(d.name)}</strong><small>${esc(d.id)} · ${esc(d.firmware)}</small></div>${onlineBadge(d)}</div><div class="device-readings">${d.profile==='climate'?`<div><label>Nhiệt độ</label><strong>${d.latest?.temperature??'—'}<small>°C</small></strong></div><div><label>Độ ẩm</label><strong>${d.latest?.humidity??'—'}<small>%</small></strong></div><div><label>Độ sáng tương đối</label><strong>${d.latest?.light_percent??'—'}<small>%</small></strong></div>`:`<div><label>Độ sáng tương đối</label><strong>${d.latest?.light_percent??'—'}<small>%</small></strong></div><div><label>Trạng thái đèn</label><strong>${d.connection!=='online'?'Chưa rõ':d.reported_state.light===undefined?'Chưa xác nhận':d.reported_state.light?'Bật':'Tắt'}</strong></div>`}</div>${window.NodoGas.panel(d)}<div class="device-meta"><span>Vòng đời</span>${lifecycleBadge(d)}</div><div class="device-meta"><span>Vị trí</span><strong>${esc(d.location)}</strong></div><div class="device-meta"><span>Người phụ trách</span><strong>${esc(d.owner_name||'Chưa gán')}</strong></div><div class="flex justify-between items-center mt-5"><span class="inline-info">${d.last_seen?relative(d.last_seen):'Chưa nhận heartbeat'}</span>${button('device-detail','Chi tiết thiết bị','arrow','btn-secondary',`data-id="${d.id}"`)}</div></article>`).join('')}</div>${rows.length?'':empty('Chưa có thiết bị phù hợp','Thử bộ lọc khác hoặc đăng ký thiết bị mới.')}`;
}
function usersHTML(rows){rows=rows.filter(u=>matches(u.name,u.email,u.role));return heading('Quản lý người dùng','Tài khoản, vai trò và quyền truy cập vào từng thiết bị.',button('new-user','Thêm người dùng'))+`<div class="panel table-wrap"><table><thead><tr><th>NGƯỜI DÙNG</th><th>EMAIL</th><th>VAI TRÒ</th><th>TRẠNG THÁI</th><th>NGÀY TẠO</th><th></th></tr></thead><tbody>${rows.map(u=>`<tr><td><div class="flex items-center gap-3"><span class="avatar">${initials(u.name)}</span><strong>${esc(u.name)} ${u.id===S.user.id?'<span class="muted">(Bạn)</span>':''}</strong></div></td><td>${esc(u.email)}</td><td>${badge({admin:'Admin',operator:'Operator',viewer:'Viewer'}[u.role],{admin:'purple',operator:'blue'}[u.role])}</td><td>${badge(u.status==='active'?'Hoạt động':'Đã khóa',u.status==='active'?'green':'red')}</td><td>${dt(u.created_at,true)}</td><td><button class="icon-btn" data-action="edit-user" data-id="${u.id}" aria-label="Sửa ${esc(u.name)}">${icon('edit')}</button></td></tr>`).join('')}</tbody></table>${rows.length?'':empty('Không tìm thấy người dùng')}</div><div class="form-note">Admin quản lý toàn hệ thống. Operator điều khiển các thiết bị được gán sở hữu. Viewer chỉ xem các thiết bị được cấp quyền.</div>`;}
function commandsHTML(rows){rows=rows.filter(c=>matches(c.device_name,c.device_id,c.kind,c.status)&&(S.filter==='all'||c.status===S.filter));return heading('Lịch sử điều khiển','Theo dõi lệnh gửi đi, xác nhận từ node và kết quả thực hiện.',button('refresh','Làm mới','refresh','btn-secondary'))+filtersHTML(`<select id="page-filter" aria-label="Lọc trạng thái lệnh"><option value="all">Tất cả trạng thái</option>${Object.entries(commandNames).map(([k,v])=>`<option value="${k}" ${S.filter===k?'selected':''}>${v}</option>`).join('')}</select>`)+`<div class="panel table-wrap"><table><thead><tr><th>THIẾT BỊ / MÃ LỆNH</th><th>THAO TÁC</th><th>NỘI DUNG</th><th>KẾT QUẢ</th><th>THỜI GIAN GỬI</th></tr></thead><tbody>${rows.map(c=>`<tr><td><strong>${esc(c.device_name)}</strong><span class="subtext mono">${esc(c.id.slice(0,8))}</span></td><td>${badge(c.kind==='config'?'Cấu hình':'Điều khiển','blue')}</td><td><span class="mono">${esc(JSON.stringify(c.payload))}</span></td><td>${commandBadge(c)}<span class="subtext">${esc(c.result||'Đợi node phản hồi')}</span></td><td>${dt(c.created_at,true)}</td></tr>`).join('')}</tbody></table>${rows.length?'':empty('Chưa có lệnh điều khiển','Lệnh của operator và kết quả ACK sẽ được lưu tại đây để admin giám sát.','command')}</div><div class="form-note">Lệnh có thời hạn 15 giây. Chỉ phản hồi ACK từ node mới chuyển lệnh sang “Đã áp dụng”. MQTT PUBACK xác nhận việc truyền bản tin đến broker.</div>`;}
function alertsHTML(rows){rows=rows.filter(a=>matches(a.message,a.device_name)&&(S.filter==='all'||a.status===S.filter));return heading('Cảnh báo & sự kiện','Phát hiện bất thường, theo dõi và xác nhận các cảnh báo trong hệ thống.',button('refresh','Làm mới','refresh','btn-secondary'))+filtersHTML(`<select id="page-filter" aria-label="Lọc cảnh báo"><option value="all">Tất cả cảnh báo</option><option value="open" ${S.filter==='open'?'selected':''}>Chưa xử lý</option><option value="acknowledged" ${S.filter==='acknowledged'?'selected':''}>Đã xác nhận</option></select>`)+`<div class="panel alert-list-full">${rows.map(a=>alertItem(a,true)).join('')||empty('Không có cảnh báo phù hợp','Cảnh báo mới sẽ được ghi nhận khi vượt ngưỡng hoặc node mất kết nối.','shield')}</div>`;}
function auditHTML(rows){rows=rows.filter(a=>matches(a.actor_name,a.action,a.target,a.detail));return heading('Nhật ký hệ thống','Dấu vết các thao tác quản trị, truy cập và thay đổi trong hệ thống.',button('refresh','Làm mới','refresh','btn-secondary'))+`<div class="panel table-wrap"><table><thead><tr><th>THỜI GIAN</th><th>NGƯỜI THỰC HIỆN</th><th>HOẠT ĐỘNG</th><th>ĐỐI TƯỢNG</th><th>CHI TIẾT</th></tr></thead><tbody>${rows.map(a=>`<tr><td>${dt(a.created_at,true)}</td><td>${esc(a.actor_name)}</td><td><strong>${esc(actionNames[a.action]||a.action)}</strong><span class="subtext mono">${esc(a.action)}</span></td><td class="mono">${esc(a.target)}</td><td title="${esc(a.detail)}">${esc(a.detail.length>85?a.detail.slice(0,85)+'…':a.detail)}</td></tr>`).join('')}</tbody></table>${rows.length?'':empty('Chưa có bản ghi phù hợp','','audit')}</div>`;}
function telemetryHTML(rows){return heading('Dữ liệu cảm biến','Theo dõi xu hướng, độ mới của số đo và lịch sử theo từng node.',button('export','Xuất CSV','download','btn-secondary'))+window.NodoTelemetry.view({rows,devices:S.devices,filter:S.filter,hours:S.hours,search:S.search,broker:S.overview?.broker,demo:S.demo});}
function settingsHTML(data){
 const w=data.workspace,isAdmin=S.user.role==='admin',disabled=isAdmin?'':'disabled';
 return heading('Cấu hình toàn hệ thống','Thiết lập chung cho các ESP32 đang được hệ thống quản lý.')+`<div class="config-layout"><section class="panel"><div class="panel-header"><div><h2 class="panel-title">Giám sát & lưu trữ</h2><p class="panel-subtitle">Áp dụng chung cho các node · không thay ngưỡng cảm biến riêng</p></div>${badge(data.demo?'DEMO MODE':'HARDWARE MODE',data.demo?'orange':'green')}</div><form id="settings-form"><div class="settings-body"><label class="field">Tên hệ thống<input name="name" required minlength="2" maxlength="100" value="${esc(w.name)}" ${disabled}><small>Tên chung của hệ thống; độc lập với tên nhà và phòng.</small></label><div class="form-grid mt-4"><label class="field">Ngưỡng offline (giây)<input name="offlineSeconds" type="number" min="15" max="300" required value="${w.offlineSeconds}" ${disabled}><small>Node active không gửi heartbeat trong thời gian này sẽ được xem là offline.</small></label><label class="field">Số đo quá cũ sau (giây)<input name="dataStaleSeconds" type="number" min="20" max="3600" required value="${w.dataStaleSeconds||60}" ${disabled}><small>Heartbeat còn nhưng không có số đo mới thì dữ liệu được đánh dấu cũ.</small></label><label class="field">Giữ lịch sử cảm biến (ngày)<input name="retentionDays" type="number" min="1" max="365" required value="${w.retentionDays}" ${disabled}><small>Số đo quá hạn được dọn tự động mỗi phút.</small></label><label class="field">Múi giờ<input value="Asia/Ho_Chi_Minh (UTC+7)" disabled><small>Dùng để hiển thị thời gian.</small></label></div><div class="form-error" hidden></div></div>${isAdmin?'<div class="modal-footer"><button class="btn btn-primary" type="submit">Lưu cấu hình chung</button></div>':''}</form></section><aside class="config-side"><section class="panel"><div class="panel-header"><h2 class="panel-title">Kết nối MQTT</h2>${badge(data.broker.connected?'Đã kết nối':'Mất kết nối',data.broker.connected?'green':'red')}</div><div class="settings-body"><p class="config-copy">Trạng thái kết nối giữa backend và broker. Mỗi ESP32 có tài khoản và heartbeat riêng.</p><div class="config-counts"><div><strong>${S.devices.length}</strong><span>Node đăng ký</span></div><div><strong>${S.devices.filter(d=>d.connection==='online').length}</strong><span>Node online</span></div></div>${data.broker.error?'<p class="form-note">'+esc(data.broker.error)+'</p>':''}<p class="config-copy">Broker kết nối không đồng nghĩa tất cả ESP32 đang online. Xem từng node tại Thiết bị.</p><a href="#devices" class="btn btn-secondary">Xem các thiết bị →</a></div></section><div class="form-note">Thông tin broker được cấu hình qua biến môi trường. Ngưỡng quạt, đèn và gas nằm trong cấu hình từng thiết bị.</div></aside></div>`;
}

const guideSections=[['users','Người dùng & phân quyền',['Tạo và cập nhật tài khoản, vai trò, trạng thái.','Đăng nhập, đăng xuất, đổi mật khẩu; băm mật khẩu.','Gán chủ sở hữu và chia sẻ quyền xem từng node.','Kiểm tra quyền tại backend; thu hồi phiên khi khóa.']],['cpu','Vòng đời thiết bị',['Registered → Provisioned → Active.','Bảo trì, tạm khóa, kích hoạt lại và ngừng sử dụng.','Định danh, tài khoản MQTT riêng; lưu phiên bản firmware.','Theo dõi online/offline độc lập với vòng đời.']],['chart','Dữ liệu & giám sát',['Nhận telemetry, kiểm tra kiểu dữ liệu và khoảng giá trị.','Chống bản tin trùng bằng deviceId + bootId + seq.','Dashboard, biểu đồ, lịch sử, bộ lọc và xuất CSV.','Heartbeat, cảnh báo nhiệt độ và mất kết nối.']],['command','Điều khiển & tự động',['Auto/Manual; ngưỡng bật/tắt riêng để tránh dao động.','Gửi lệnh, chờ ACK, lưu kết quả hoặc timeout.','Quạt/còi cho node môi trường; đèn cho node ánh sáng.','Quy tắc tự động chạy ở ESP32 khi mất mạng.']],['shield','Bảo mật & truy vết',['Cookie HttpOnly, SameSite; CSRF token; hạn chế đăng nhập.','Phân quyền theo vai trò và từng thiết bị.','Audit log cho thao tác quan trọng; không lưu mật khẩu node.','Thu hồi kết nối tại broker khi khóa thiết bị ở chế độ thật.']],['book','Tích hợp & phần cần hoàn thiện',['Kết nối Mosquitto, cấu hình TLS, Dynamic Security và ACL.','Kiểm thử firmware thật: ACK, reconnect, LWT và lệnh hết hạn.','Chạy đo độ trễ, kiểm thử tải và kiểm tra nguồn phần cứng.','Backup/restore database và triển khai HTTPS trước khi đưa lên mạng.']]];
function guideHTML(){return heading('Phạm vi quản trị & tích hợp','Danh sách công việc dành cho backend của hệ thống hai node ESP32.',`<a class="btn btn-secondary" href="/docs/ADMIN-CHECKLIST.md" target="_blank" rel="noopener">${icon('book')}Checklist đầy đủ</a>`)+`<div class="demo-banner"><div>${icon('cpu')}<span><strong>Hai node độc lập:</strong> Node 01 — nhiệt độ, độ ẩm, quạt & còi. Node 02 — ánh sáng & đèn.</span></div></div><div class="checklist">${guideSections.map(([ico,title,items])=>`<section class="checklist-card"><h2>${icon(ico)}${title}</h2><ul>${items.map(item=>`<li>${item}</li>`).join('')}</ul></section>`).join('')}</div><div class="form-note">Tài liệu bàn giao: <a href="/docs/MQTT-CONTRACT.md" target="_blank" rel="noopener">MQTT contract ↗</a> &nbsp; · &nbsp; <a href="/docs/API.md" target="_blank" rel="noopener">API reference ↗</a>. Tính năng OTA và AI để ở giai đoạn mở rộng sau khi luồng cơ bản hoạt động ổn định.</div>`;}
function adminHomeLabel(h){
 const owner=S.homeOwners?.find(u=>u.id===h.owner_id);
 const name=h.name==='Nhà của tôi'?'Nhà riêng':h.name;
 return name+' — Chủ nhà: '+(owner?.name||h.owner_id);
}
function homesHTML(){
 return heading('Quản lý ngôi nhà','Giám sát chủ nhà, thiết bị và tình trạng kết nối.')+'<div class="device-grid">'+S.homes.map(h=>{
  const owner=S.homeOwners?.find(u=>u.id===h.owner_id);
  return '<article class="device-full-card"><h2>'+esc(adminHomeLabel(h))+'</h2><p class="inline-info">'+esc(h.address||'Chưa có địa chỉ')+'</p><div class="device-meta"><span>Chủ nhà</span><strong>'+esc(owner?.name||h.owner_id)+'</strong></div><p class="inline-info">'+esc(owner?.email||'')+'</p><div class="device-meta"><span>Thiết bị online</span><strong>'+h.counts.online+' / '+h.counts.devices+'</strong></div><div class="device-meta"><span>Dữ liệu cũ / thiếu</span><strong>'+h.counts.stale+'</strong></div><div class="device-meta"><span>Node báo lỗi</span><strong>'+h.counts.faults+'</strong></div><button class="btn btn-secondary mt-4" data-action="home-detail" data-id="'+esc(h.id)+'">Chi tiết nhà →</button></article>';
 }).join('')+'</div>'+(S.homes.length?'':empty('Chưa có ngôi nhà nào','Nhà xuất hiện sau khi operator tạo nhà trên web.'));
}
async function homeDetail(id){
 const h=await api('/homes/'+encodeURIComponent(id)),owner=h.members.find(m=>m.owner);
 modal(esc(adminHomeLabel(h)),'Giám sát nhà · Admin không điều khiển thiết bị',`<dl class="detail-grid"><div><dt>Chủ nhà</dt><dd>${esc(owner?.name||h.owner_id)}</dd></div><div><dt>Email</dt><dd>${esc(owner?.email||'—')}</dd></div><div><dt>Số phòng</dt><dd>${h.rooms.length}</dd></div><div><dt>Số thiết bị</dt><dd>${h.devices.length}</dd></div></dl><h3>Các phòng</h3><div class="history-list">${h.rooms.map(r=>'<div class="history-row"><strong>'+esc(r.name)+'</strong><span>'+h.devices.filter(d=>d.room_id===r.id).length+' node</span></div>').join('')||'<p class="inline-info">Chưa tạo phòng.</p>'}</div><h3>Thiết bị trong nhà</h3>${deviceTable(h.devices)}<h3>Hoạt động gần đây</h3>${activityRows(h.audit.slice(0,10))}`);
}

async function render(quiet=false){
  const version=++S.renderVersion,page=S.page;
  try{
    let html,chartRows=null,light=false;
    if(!quiet)$('#content').setAttribute('aria-busy','true');
    if(page==='overview'){
      const o=await api('/overview');S.overview=o;S.devices=o.devices;html=overviewHTML(o);
      const climate=o.devices.find(d=>d.profile==='climate');chartRows=climate?await api(`/telemetry?deviceId=${encodeURIComponent(climate.id)}&hours=${S.chartHours}&limit=500`):[];
    }else{
      S.devices=await api('/devices');
      if(page==='devices')html=devicesHTML();
      if(page==='ai'){window.NodoAI.configure({api:(path,method,body)=>api(path,{method,body}),user:S.user,toast,reload:()=>render(true),allSecurity:true});html=await window.NodoAI.view();}
      if(page==='homes'){[S.homes,S.homeOwners]=await Promise.all([api('/homes'),api('/users')]);html=homesHTML();}
      if(page==='users'){S.users=await api('/users');html=usersHTML(S.users);}
      if(page==='commands')html=commandsHTML(await api('/commands'));
      if(page==='alerts')html=alertsHTML(await api('/alerts'));
      if(page==='audit'){
        [S.homes,S.homeOwners]=await Promise.all([api('/homes'),api('/users')]);
        const rows=await api('/audit'+(S.filter!=='all'?'?homeId='+encodeURIComponent(S.filter):''));
        const filter=filtersHTML(`<label class="audit-house-filter">Nhà của operator<select id="page-filter" aria-label="Lọc nhật ký theo nhà"><option value="all">Toàn hệ thống / Tất cả nhà</option>${S.homes.map(h=>`<option value="${esc(h.id)}" ${S.filter===h.id?'selected':''}>${esc(adminHomeLabel(h))}</option>`).join('')}</select></label>`);
        html=auditHTML(rows);const point=html.indexOf('<div class="panel table-wrap">');html=html.slice(0,point)+filter+html.slice(point);
      }
      if(page==='telemetry'){S.overview=await api('/overview');S.devices=S.overview.devices;chartRows=await api(`/telemetry?hours=${S.hours}&limit=1000${S.filter!=='all'?'&deviceId='+encodeURIComponent(S.filter):''}`);light=S.devices.find(d=>d.id===S.filter)?.profile==='lighting';html=telemetryHTML(chartRows);}
      if(page==='settings'){
        const settings=await api('/settings');html=settingsHTML(settings);
        html+=`<div class="form-note">Database: <strong>${esc(settings.database.provider)}</strong> · ${esc(settings.database.name)} · ${badge(settings.database.connected?'Đã kết nối':'Mất kết nối',settings.database.connected?'green':'red')}</div>`;
      }
      if(page==='guide')html=guideHTML();
    }
    if(version!==S.renderVersion)return;
    if(S.chart){S.chart.destroy();S.chart=null;}
    $('#content').innerHTML=html||empty('Không có quyền truy cập');$('#content').removeAttribute('aria-busy');navigation();
    if(S.overview?.counts.security_alerts)$('#content').insertAdjacentHTML('afterbegin',`<div class="ai-security-banner"><span>Có ${S.overview.counts.security_alerts} cảnh báo giờ đăng nhập cần kiểm tra.</span><a href="#ai">AI & bảo mật ↗</a></div>`);
    if(page==='telemetry')S.chart=window.NodoTelemetry.chart();else if(chartRows)await drawChart('#environment-chart',chartRows,light);
  }catch(e){if(!quiet)toast(e.message,true);$('#content').removeAttribute('aria-busy');}
}
function route(){const page=location.hash.slice(1)||'overview';S.page=[...pages.map(p=>p[0]),'guide'].includes(page)?page:'overview';if(S.user.role!=='admin'&&['users','audit'].includes(S.page))S.page='overview';S.filter='all';S.search='';$('#global-search').value='';closeSidebar();render();}
function modal(title,description,body,footer='',form=''){
  $('#modal-content').innerHTML=`${form?`<form id="${form}" method="dialog">`:''}<div class="modal-header"><div><span class="eyebrow">NODO / ADMIN</span><h2>${title}</h2><p>${description}</p></div><button class="icon-btn" type="button" data-action="close-modal" aria-label="Đóng hộp thoại">${icon('close')}</button></div><div class="modal-body">${body}<div class="form-error" hidden></div></div>${footer?`<div class="modal-footer">${footer}</div>`:''}${form?'</form>':''}`;
  if(!$('#modal').open)$('#modal').showModal();
}
const formFooter=text=>`<button type="button" class="btn btn-secondary" data-action="close-modal">Hủy</button><button type="submit" class="btn btn-primary">${text}</button>`;
async function userForm(id){
  const u=id?S.users.find(u=>u.id===id):null;
  modal(u?'Cập nhật người dùng':'Thêm người dùng','Vai trò và phạm vi được kiểm tra tại backend.',`<div class="form-grid"><input type="hidden" name="id" value="${u?.id||''}"><label class="field full">Họ và tên<input name="name" required minlength="2" maxlength="80" value="${esc(u?.name||'')}"></label><label class="field full">Email<input name="email" type="email" required maxlength="120" value="${esc(u?.email||'')}"></label><label class="field">Vai trò<select name="role">${['admin','operator','viewer'].map(role=>`<option value="${role}" ${(u?.role||'operator')===role?'selected':''}>${role}</option>`).join('')}</select></label><label class="field">Trạng thái<select name="status"><option value="active">Hoạt động</option><option value="disabled" ${u?.status==='disabled'?'selected':''}>Đã khóa</option></select></label><label class="field full">${u?'Mật khẩu mới (để trống nếu giữ nguyên)':'Mật khẩu'}<input name="password" type="password" minlength="10" maxlength="128" ${u?'':'required'} autocomplete="new-password"><small>Tối thiểu 10 ký tự. Mật khẩu được băm trước khi lưu.</small></label></div>`,formFooter(u?'Lưu thay đổi':'Tạo tài khoản'),'user-form');
}
async function deviceForm(id){
 const d=id?await api('/devices/'+id):null;
 modal(d?'Thông tin thiết bị':'Đăng ký thiết bị','Operator nhận thiết bị bằng mã do admin cấp.',`<div class="form-grid"><input type="hidden" name="editing" value="${d?.id||''}">${d?'':`<label class="field">Device ID<input name="id" required pattern="[a-z0-9][a-z0-9-]{2,39}" placeholder="hw-climate-01"></label><label class="field">Loại node<select name="profile"><option value="climate">DHT + gas + LDR / quạt, còi, đèn</option><option value="lighting">LDR + đèn</option></select></label>`}<label class="field full">Tên thiết bị<input name="name" required minlength="2" maxlength="80" value="${esc(d?.name||'')}"></label>${!d?.home_id?`<label class="field full">Vị trí lưu kho<input name="location" required maxlength="100" value="${esc(d?.location||'Kho thiết bị')}"></label>`:''}</div>${d?.home_id?'<div class="form-note">Thiết bị đã được chủ nhà nhận. Phòng và thành viên do chủ nhà quản lý.</div>':'<div class="form-note">Sau khi cấp kết nối, tạo mã nhận thiết bị để bàn giao cho operator.</div>'}`,formFooter(d?'Lưu thông tin':'Đăng ký thiết bị'),'device-form');
}

async function detail(id){
  const d=await api('/devices/'+id),states=['registered','provisioned','active'];
  const labels={provisioned:'Cấp quyền kết nối',active:d.lifecycle==='locked'?'Mở khóa & kích hoạt':'Kích hoạt',maintenance:'Chuyển bảo trì',locked:'Khóa thiết bị',decommissioned:'Ngừng sử dụng'};
  const actuators=d.profile==='climate'?['fan','buzzer','light']:['light'];
  modal(esc(d.name),`${esc(d.id)} · ${esc(d.hardware)} · Firmware ${esc(d.firmware)}`,`<section class="device-state-summary"><div><span>Kết nối hiện tại</span>${onlineBadge(d)}</div><div><span>Quyền vận hành</span>${lifecycleBadge(d)}</div></section>${d.connection!=='online'?'<p class="device-offline-note">Thiết bị đang offline, chưa thể gửi lệnh hoặc cấu hình.</p>':''}<div class="lifecycle-track">${states.map((s,i)=>`<div class="lifecycle-step ${states.indexOf(d.lifecycle)>i?'done':''} ${d.lifecycle===s?'current':''}">${lifeNames[s]}</div>`).join('')}</div>${window.NodoGas.panel(d)}<dl class="detail-grid"><div><dt>Vị trí</dt><dd>${esc(d.location)}</dd></div><div><dt>Người phụ trách</dt><dd>${esc(d.owner_name||'Chưa gán')}</dd></div><div><dt>Heartbeat gần nhất</dt><dd>${dt(d.last_seen,true)}</dd></div><div><dt>MQTT username</dt><dd class="mono">${esc(d.mqtt_username||'Chưa cấp')}</dd></div></dl>${d.fault?`<div class="form-error">${esc(d.fault)}</div>`:''}<div class="detail-actions">${canWrite(d)&&d.lifecycle==='active'?button('config-device',d.pendingConfig?'Đang chờ xác nhận cấu hình':'Cấu hình ngưỡng','settings','btn-secondary',`data-id="${d.id}" ${d.pendingCommand||d.connection!=='online'?'disabled':''}`):''}${S.user.role==='admin'&&d.lifecycle!=='decommissioned'?button('edit-device','Sửa thông tin','edit','btn-secondary',`data-id="${d.id}"`):''}</div>${S.user.role==='operator'&&canWrite(d)&&d.lifecycle==='active'?`<div class="form-note"><strong>Điều khiển đầu ra</strong><div class="flex gap-4 mt-3">${actuators.map(a=>`<div class="flex items-center gap-2"><span>${{fan:'Quạt',buzzer:'Còi',light:'Đèn'}[a]}</span><button class="toggle ${d.reported_state[a]?'on':''}" role="switch" aria-checked="${!!d.reported_state[a]}" aria-label="${{fan:'Quạt',buzzer:'Còi',light:'Đèn'}[a]}" data-action="toggle-actuator" data-id="${d.id}" data-actuator="${a}" data-value="${!d.reported_state[a]}" ${d.connection!=='online'||(a==='buzzer'&&d.gas_alarm_active&&d.reported_state.buzzer)?'disabled':''}></button></div>`).join('')}</div><small>Đầu ra cập nhật sau ACK; quy tắc tự động vẫn hoạt động.</small></div>`:''}${S.user.role==='admin'?`<div class="history-list"><h3>Thao tác vòng đời</h3><div class="detail-actions">${d.allowedTransitions.map(target=>button('lifecycle',labels[target],target==='locked'?'lock':target==='decommissioned'?'close':'arrow',target==='decommissioned'?'btn-danger':'btn-secondary',`data-id="${d.id}" data-state="${target}"`)).join('')||'<span class="inline-info">Đã ngừng sử dụng. Lịch sử được giữ lại để tra cứu.</span>'}</div></div>`:''}${S.demo&&S.user.role==='admin'&&d.lifecycle==='active'?`<div class="history-list"><h3>Kiểm thử kết nối · Demo</h3><div class="detail-actions">${button('demo-offline','Ngắt node giả lập','wifi','btn-secondary',`data-id="${d.id}"`)}${button('demo-online','Kết nối lại','refresh','btn-secondary',`data-id="${d.id}"`)}</div></div>`:''}<div class="history-list"><h3>Lịch sử vòng đời</h3>${d.events.map(e=>`<div class="history-row"><span>${esc(lifeNames[e.to_state]||e.to_state)} · ${esc(e.actor_name)}</span><time>${dt(e.created_at,true)}</time></div>`).join('')}</div>`);
}
async function configForm(id){const d=await api('/devices/'+id),c=d.config;modal('Cấu hình '+esc(d.name),'Tham số chỉ có hiệu lực sau khi node gửi ACK.',`<input name="id" type="hidden" value="${d.id}"><div class="form-grid">${d.profile==='climate'?`<label class="field">Bật quạt từ (°C)<input name="fanOn" type="number" min="15" max="60" step="0.1" required value="${c.fanOn}"></label><label class="field">Tắt quạt khi ≤ (°C)<input name="fanOff" type="number" min="10" max="55" step="0.1" required value="${c.fanOff}"></label><label class="field full">Cảnh báo nhiệt độ từ (°C)<input name="temperatureAlert" type="number" min="20" max="75" step="0.1" required value="${c.temperatureAlert}"></label>${window.NodoGas.fields(c)}<label class="field">Bật đèn khi độ sáng ≤ (%)<input name="lightOn" type="number" min="0" max="99" step="0.1" required value="${c.lightOn}"></label><label class="field">Tắt đèn khi độ sáng ≥ (%)<input name="lightOff" type="number" min="1" max="100" step="0.1" required value="${c.lightOff}"></label>`:`<label class="field">Bật đèn khi độ sáng ≤ (%)<input name="lightOn" type="number" min="0" max="99" required value="${c.lightOn}"></label><label class="field">Tắt đèn khi độ sáng ≥ (%)<input name="lightOff" type="number" min="1" max="100" required value="${c.lightOff}"></label>`}</div><div class="form-note">Ngưỡng bật và tắt khác nhau giúp tránh đóng/ngắt liên tục khi giá trị đo dao động gần ngưỡng.</div>`,formFooter('Gửi cấu hình xuống node'),'config-form');}
function closeSidebar(){$('#sidebar').classList.remove('open');$('#sidebar-backdrop').hidden=true;}
async function perform(action,el){
  const id=el.dataset.id;
  if(action==='menu'){$('#sidebar').classList.toggle('open');$('#sidebar-backdrop').hidden=!$('#sidebar').classList.contains('open');return;}
  if(action==='close-modal'){$('#modal').close();return;}
  if(action==='home-detail')return homeDetail(el.dataset.id);
  if(action==='logout'){if(S.loggingOut)return;S.loggingOut=true;try{await api('/auth/logout',{method:'POST'});location.replace('/login');}catch(error){S.loggingOut=false;throw error;}return;}
  if(action==='notifications'){location.hash='alerts';return;}
  if(action==='refresh'){await render();toast('Đã cập nhật dữ liệu mới nhất.');return;}
  if(action==='new-user'||action==='edit-user')return userForm(id);
  if(action==='new-device'||action==='edit-device')return deviceForm(id);
  if(action==='device-detail'){await detail(id);const d=S.devices.find(d=>d.id===id);if(S.user.role==='admin'&&d&&!d.home_id&&!d.owner_id&&['provisioned','active'].includes(d.lifecycle))$('#modal .detail-actions').insertAdjacentHTML('beforeend',button('claim-code','Tạo mã nhận thiết bị','shield','btn-secondary',`data-id="${esc(id)}"`));return;}
  if(action==='claim-code'){const r=await api('/devices/'+id+'/claim-code',{method:'POST'});modal('Mã nhận thiết bị','Bàn giao cho chủ nhà để nhận node trên web quản lý nhà. Hiệu lực 24 giờ.',`<div class="credential-box">Device ID: ${esc(r.deviceId)}<br>Mã: ${esc(r.code)}</div><p class="inline-info">Mã chỉ dùng một lần; khác với mật khẩu MQTT.</p>`);return;}
  if(action==='config-device')return configForm(id);
  if(action==='telemetry-period'){S.hours=Number(el.dataset.hours);return render(true);}
  if(action==='chart-period'){S.chartHours=Number(el.dataset.hours);return render(true);}
  if(action==='ack-alert'){await api('/alerts/'+id+'/acknowledge',{method:'PATCH'});toast('Đã xác nhận cảnh báo.');return render(true);}
  if(action==='lifecycle'){
    const target=el.dataset.state;
    if(['locked','decommissioned'].includes(target)){
      modal(target==='locked'?'Khóa thiết bị?':'Ngừng sử dụng thiết bị?',target==='locked'?'Thu hồi quyền kết nối của node.':'Thao tác này kết thúc vòng đời; lịch sử vẫn được lưu.',`<p class="inline-info">Thiết bị <strong>${esc(id)}</strong> sẽ chuyển sang trạng thái <strong>${lifeNames[target]}</strong>.${target==='decommissioned'?' Không thể kích hoạt lại thiết bị này.':''}</p>`,`<button class="btn btn-secondary" data-action="device-detail" data-id="${id}">Quay lại</button>${button('confirm-lifecycle','Xác nhận','check','btn-danger',`data-id="${id}" data-state="${target}"`)}`);return;
    }
    return changeLifecycle(id,target);
  }
  if(action==='confirm-lifecycle')return changeLifecycle(id,el.dataset.state);
  if(action==='toggle-actuator'){await api('/devices/'+id+'/commands',{method:'POST',body:{actuator:el.dataset.actuator,value:el.dataset.value==='true'}});toast('Đã gửi lệnh. Đang chờ node xác nhận.');$('#modal').close();return render(true);}
  if(action==='demo-offline'||action==='demo-online'){await api('/demo/devices/'+id+'/connection',{method:'POST',body:{offline:action==='demo-offline'}});toast(action==='demo-offline'?'Đã ngắt node giả lập.':'Đã kết nối lại node.');await detail(id);return render(true);}
  if(action==='export'){const params=`hours=${S.hours}&limit=2000&format=csv${S.filter!=='all'?'&deviceId='+encodeURIComponent(S.filter):''}`;const response=await fetch('/api/telemetry?'+params);if(!response.ok)throw new Error('Không thể xuất dữ liệu.');const url=URL.createObjectURL(await response.blob());const a=document.createElement('a');a.href=url;a.download='nodo-telemetry.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Đã xuất dữ liệu CSV.');}
}
async function changeLifecycle(id,state){const result=await api('/devices/'+id+'/lifecycle',{method:'POST',body:{state}});toast('Đã chuyển trạng thái thiết bị.');if(result.credentials){modal('Thông tin kết nối mới','Mật khẩu chỉ hiển thị một lần. Hãy bàn giao trực tiếp cho người làm phần cứng.',`<div class="credential-box">${esc(JSON.stringify(result.credentials,null,2))}</div><div class="form-note">${result.credentials.simulated?'Thông tin demo, chưa được tạo trên broker thật.':'Thông tin đã được tạo trên Mosquitto Dynamic Security.'} Không đưa mật khẩu vào GitHub.</div>`);}else await detail(id);await render(true);}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const wasDisabled=el.disabled;el.disabled=true;Promise.resolve(perform(el.dataset.action,el)).catch(e=>{const error=$('#modal').open?$('#modal .modal-body .form-error'):null;if(error){error.textContent=e.message;error.hidden=false;}else toast(e.message,true);}).finally(()=>{if(el.isConnected)el.disabled=wasDisabled;});});
document.addEventListener('submit',async event=>{
  const form=event.target,formId=form.getAttribute('id');if(!['user-form','device-form','config-form','settings-form','password-form'].includes(formId))return;
  event.preventDefault();const submit=form.querySelector('[type="submit"]');submit.disabled=true;const err=form.querySelector('.form-error');err.hidden=true;
  try{
    const values=Object.fromEntries(new FormData(form));
    if(formId==='user-form'){const id=values.id;delete values.id;if(!values.password)delete values.password;await api('/users'+(id?'/'+id:''),{method:id?'PATCH':'POST',body:values});}
    if(formId==='device-form'){const id=values.editing;delete values.editing;await api('/devices'+(id?'/'+id:''),{method:id?'PATCH':'POST',body:values});}
    if(formId==='config-form'){const id=values.id;delete values.id;for(const key of Object.keys(values))if(key!=='mode')values[key]=Number(values[key]);await api('/devices/'+id+'/config',{method:'PATCH',body:values});toast('Đã gửi cấu hình. Chờ node xác nhận trước khi áp dụng.');}
    if(formId==='settings-form'){values.timezone='Asia/Ho_Chi_Minh';values.offlineSeconds=Number(values.offlineSeconds);values.retentionDays=Number(values.retentionDays);values.dataStaleSeconds=Number(values.dataStaleSeconds);await api('/settings',{method:'PATCH',body:values});}
    if(formId==='password-form'){await api('/auth/password',{method:'PATCH',body:values});form.reset();}
    if(formId!=='config-form')toast('Đã lưu thay đổi.');if($('#modal').open)$('#modal').close();await render(true);
  }catch(e){err.textContent=e.message;err.hidden=false;}finally{submit.disabled=false;}
});
document.addEventListener('change',event=>{if(event.target.id==='page-filter'){S.filter=event.target.value;render(true);}if(event.target.id==='hours-filter'){S.hours=Number(event.target.value);render(true);}});
let searchTimer;$('#global-search').addEventListener('input',event=>{S.search=event.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>render(true),250);});
$('#sidebar-backdrop').addEventListener('click',closeSidebar);
$('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)$('#modal').close();}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();$('#global-search').focus();}if(e.key==='Escape')closeSidebar();});
window.addEventListener('hashchange',route);
function connect(){
  S.socket=new WebSocket(`${location.protocol==='https:'?'wss:':'ws:'}//${location.host}/ws`);
  S.socket.onopen=()=>{$('#connection-label').textContent='Live';$('#sidebar-status').textContent='Kết nối hệ thống ổn định';};
  let refreshTimer;
  S.socket.onmessage=event=>{const data=JSON.parse(event.data);if(data.type==='connected')return;clearTimeout(refreshTimer);refreshTimer=setTimeout(async()=>{
    try{const overview=await api('/overview');S.overview=overview;navigation();if(!$('#modal').open&&!window.NodoAI?.isDialogOpen()&&!['settings','guide','users'].includes(S.page)&&!S.search)await render(true);}catch{}
  },250);};
  S.socket.onclose=event=>{$('#connection-label').textContent='Đang kết nối lại';$('#sidebar-status').textContent='Đang kết nối lại hệ thống';if(event.code===1008){location.replace('/login');return;}setTimeout(connect,3000);};
}
(async()=>{icons();try{const auth=await api('/auth/me');S.user=auth.user;S.csrf=auth.csrfToken;S.demo=auth.demo;S.overview=await api('/overview');route();connect();}catch(e){toast(e.message,true);}})();
